// SUPER TINY NAV. two links. that’s it.
import React from "react";
import { Link } from "react-router-dom";

function NavBar() {
  return (
    <nav className="nav">
      <Link to="/">Home</Link>
      <span> / </span>
      <Link to="/about">About</Link>
    </nav>
  );
}

export default NavBar;
